import React, { useEffect, useState } from "react";
import {
  MapContainer,
  TileLayer,
  CircleMarker,
  Marker,
  Popup,
  Circle,
  useMap,
  GeoJSON
} from "react-leaflet";
import "leaflet/dist/leaflet.css";
import volcanoUrl from './assets/icons/volcano.svg?url';
import L from "leaflet";

// Verifica que el SVG se importe bien
console.log("volcanoUrl:", volcanoUrl);

const ChangeView = ({ coordenadas }) => {
  const map = useMap();
  useEffect(() => {
    if (coordenadas) {
      map.setView([coordenadas.lat, coordenadas.lng], 7);
    }
  }, [coordenadas, map]);
  return null;
};

const volcanoIcon = new L.Icon({
  iconUrl: volcanoUrl,
  iconRetinaUrl: volcanoUrl,
  iconSize:     [32, 32],
  iconAnchor:   [16, 32],
  popupAnchor:  [0, -32],
});

const MapaMexico = ({
  coordenadas,
  theme,
  placas = [],
  volcanes = []    // default para evitar undefined
}) => {
  const [circleScale, setCircleScale] = useState(1);
  const [opacity, setOpacity] = useState(0.6);

  // Depuración de volcanes
  console.log("Volcanes recibidos:", volcanes);
  console.log("Coords volcanes:", volcanes.map(v => [v.lat, v.lng]));

  // Depuración de placas
  useEffect(() => {
    console.log("MapaMexico recibió placas:", placas);
  }, [placas]);

  // Animación de círculo
  useEffect(() => {
    if (!coordenadas) return;
    let scale = 1, opac = 0.6;
    const interval = setInterval(() => {
      scale += 0.05;
      opac = Math.max(opac - 0.01, 0);
      setCircleScale(scale);
      setOpacity(opac);
      if (scale > 3 || opac <= 0) {
        scale = 1; opac = 0.6;
      }
    }, 50);
    return () => clearInterval(interval);
  }, [coordenadas]);

  const tileLayerURL = theme === "dark"
    ? "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
    : "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png";
  const tileLayerAttribution = theme === "dark"
    ? '&copy; <a href="https://carto.com/">CARTO</a>'
    : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';

  const placaStyle = {
    color: "#689c58",
    weight: 2,
    opacity: 0.8,
    fillOpacity: 0.1,
    fillColor: "#b3dda6"
  };
  const onEachFeature = (feature, layer) => {
    if (feature.properties) {
      layer.bindPopup(`
        <div>
          <h3>${feature.properties.nombre || 'Placa'}</h3>
          <p>${feature.properties.descripcion || ''}</p>
        </div>
      `);
    }
  };

  return (
    <div style={{ height: "100%", width: "100%" }}>
      <MapContainer
        center={[23.6345, -102.5528]}
        zoom={5}
        style={{ height: "100%", width: "100%" }}
      >
        <TileLayer
          url={tileLayerURL}
          attribution={tileLayerAttribution}
          noWrap={true}
        />

        { /* === PRUEBA 1: dibujar CircleMarkers para descartar icono === */ }
        {volcanes
          .filter(v => v.lat != null && v.lng != null)
          .map(v => (
            <CircleMarker
              key={`cm-${v.id}`}
              center={[v.lat, v.lng]}
              radius={8}
              color="red"
            >
              <Popup>{v.descripcion}</Popup>
            </CircleMarker>
        ))}

        { /* === PRUEBA 2: dibujar Marker por defecto === */ }
        {volcanes
          .filter(v => v.lat != null && v.lng != null)
          .map(v => (
            <Marker
              key={`m-${v.id}`}
              position={[v.lat, v.lng]}
              zIndexOffset={1000}
            >
              <Popup>{v.descripcion}</Popup>
            </Marker>
        ))}

        { /* === VERSIÓN FINAL: Marker con icono personalizado === */ }
        {volcanes
          .filter(v => v.lat != null && v.lng != null)
          .map(v => (
            <Marker
              key={v.id}
              position={[v.lat, v.lng]}
              icon={volcanoIcon}
              zIndexOffset={1000}
            >
              <Popup>
                <h4>{v.descripcion}</h4>
                Lat: {v.lat}<br/>
                Lng: {v.lng}
              </Popup>
            </Marker>
        ))}

        { /* === PLACAS GEOJSON === */ }
        {placas.map((placa, i) => (
          <GeoJSON
            key={placa.properties?.id || i}
            data={placa}
            style={placaStyle}
            onEachFeature={onEachFeature}
          />
        ))}

        <ChangeView coordenadas={coordenadas} />

        {coordenadas && (
          <>
            <CircleMarker
              center={[coordenadas.lat, coordenadas.lng]}
              radius={10}
              color="red"
              fillColor="red"
              fillOpacity={0.8}
            >
              <Popup>
                <b>Ubicación del Sismo</b><br/>
                Lat: {coordenadas.lat}, Lng: {coordenadas.lng}
              </Popup>
            </CircleMarker>
            <Circle
              center={[coordenadas.lat, coordenadas.lng]}
              radius={circleScale * 50000}
              color="red"
              fillColor="red"
              fillOpacity={opacity}
              stroke={false}
            />
          </>
        )}
      </MapContainer>
    </div>
  );
};

export default MapaMexico;
